function parseQuery(str) {
  if (typeof str !== 'string') {
    throw new TypeError('Argument must be a string');
  }

  // Remove leading `?`
  if (str.startsWith('?')) {
    str = str.slice(1);
  }

  // Parse the query string
  const result = Object.create(null);
  if (!str) return result;

  const pairs = str.split('&');

  for (const pair of pairs) {
    if (!pair) continue; // Skip empty segments

    const eqIndex = pair.indexOf('=');
    let key, value;

    if (eqIndex === -1) {
      key = pair;
      value = '';
    } else {
      key = pair.slice(0, eqIndex);
      value = pair.slice(eqIndex + 1);
    }

    // Skip if key is empty
    if (!key) continue;

    // Decode key and value
    key = decodeComponent(key);
    value = decodeComponent(value);

    // Handle repeated keys
    if (key in result) {
      if (!Array.isArray(result[key])) {
        result[key] = [result[key]];
      }
      result[key].push(value);
    } else {
      result[key] = value;
    }
  }

  return result;
}

function decodeComponent(str) {
  // Replace + with space
  str = str.replace(/\+/g, ' ');

  // Decode %XX escapes
  // Handle UTF-8 sequences
  const bytes = [];
  let i = 0;
  while (i < str.length) {
    if (str[i] === '%' && i + 2 < str.length) {
      const hex = str.slice(i + 1, i + 3);
      // Check if both characters are valid hex digits
      if (/^[0-9A-Fa-f]{2}$/.test(hex)) {
        bytes.push(parseInt(hex, 16));
        i += 3;
        continue;
      }
    }
    // Not a valid escape, convert character to UTF-8 bytes
    const char = str[i];
    const encoded = new TextEncoder().encode(char);
    for (const byte of encoded) {
      bytes.push(byte);
    }
    i++;
  }

  // Decode UTF-8 bytes
  try {
    return new TextDecoder('utf-8', { fatal: false }).decode(new Uint8Array(bytes));
  } catch (e) {
    return new TextDecoder('utf-8', { fatal: false }).decode(new Uint8Array(bytes));
  }
}

